    ['code' => 'gen-beh-priorities', 'type' => 'behavioral', 'lvl' => [1, 5], 'diff' => 2, 'sec' => 180, 'skills' => ['organisation', 'stress_management'],
        'fr' => ['Comment gérez-vous plusieurs priorités urgentes en même temps ? Donnez un exemple.', 'Présentez votre méthode de priorisation puis illustrez-la par une situation réelle.',
