    ['code' => 'gen-beh-difficult-client', 'type' => 'behavioral', 'lvl' => [1, 4], 'diff' => 3, 'sec' => 180, 'skills' => ['customer_orientation', 'conflict_management', 'communication'],
        'fr' => ['Racontez une situation avec un client ou un usager mécontent.', 'Décrivez votre écoute, la solution apportée et la façon dont la relation a évolué.',
            ['Écoute et reformulation|ecoute,reformule,compris,calme,empathie', 'Solution concrète|solution,propose,resolu,geste,delai,remboursement,suivi', 'Suivi et fidélisation|suivi,rappele,relation,fidel,satisfait', 'Respect des règles|regle,procedure,politique,limite'],
            ['Céder à tout sans tenir compte des règles', 'Rejeter la faute sur le client'],
