    ['code' => 'gen-beh-ethics', 'type' => 'behavioral', 'lvl' => [2, 5], 'diff' => 4, 'sec' => 210, 'skills' => ['ethics_integrity', 'decision_making'],
        'fr' => ['Avez-vous déjà été confronté à une demande contraire à l\'éthique ou aux règles ? Qu\'avez-vous fait ?', 'Montrez votre attachement aux règles, votre manière de dire non et l\'escalade éventuelle.',
