        'en' => ['Have you ever faced a request that went against ethics or rules? What did you do?', 'Show your commitment to rules, how you say no and appropriate escalation.',
            ['Nature of the dilemma|rule,ethic,procedure,complian,request,pressure', 'Reasoned refusal|refused,declined,explained,said no,risk', 'Appropriate escalation|reported,manager,compliance,escalated,raised', 'Outcome and lesson|result,outcome,learned,learnt,since'],
