    // Salary negotiation
    ['code' => 'gen-neg-expectations', 'type' => 'negotiation', 'lvl' => [1, 5], 'diff' => 3, 'sec' => 150, 'skills' => ['negotiation', 'communication'],
        'criteria_fr' => 'Fourchette argumentée par le marché et la valeur apportée, ouverture au package global, ton professionnel.',
        'criteria_en' => 'Range justified by market data and value brought, openness to the overall package, professional tone.',
        'fr' => ['Quelles sont vos prétentions salariales ?', 'Donnez une fourchette réaliste fondée sur le marché et votre expérience, et montrez que vous considérez le package global.',
            ['Fourchette chiffrée|fourchette,entre,euros,k€,brut,annuel,fcfa', 'Justification par le marché|marche,etude,benchmark,pratique,similaire', 'Justification par la valeur apportée|experience,competence,responsabilites,valeur', 'Ouverture au package global|package,avantages,variable,teletravail,formation,ouvert,discuter'],
            ['Refuser de donner un chiffre', 'Donner un chiffre sans aucune justification', 'Annoncer un montant très au-dessus du marché sans argument'],
            'D\'après les études de rémunération du secteur et les échanges avec mon réseau, un poste comparable se situe entre 42 et 46 k€ brut annuel. Compte tenu de mes cinq ans d\'expérience et de la gestion budgétaire incluse dans le poste, je me situe plutôt dans le haut de cette fourchette. Je reste ouvert à discuter du package global, notamment la part variable et la formation.',
            'fourchette,marche,experience,package'],
        'en' => ['What are your salary expectations?', 'Give a realistic range based on the market and your experience, and show you consider the overall package.',
            ['A figured range|range,between,k,gross,annual,per year,salary', 'Market based justification|market,survey,benchmark,research,similar roles', 'Value based justification|experience,skills,responsibilit,value', 'Openness to the overall package|package,benefits,bonus,remote,training,open,discuss'],
            ['Refusing to give a figure', 'A figure with no justification', 'A figure far above market with no argument'],
            'Based on sector salary surveys and my network, comparable roles pay between 42 and 46k gross per year. Given my five years of experience and the budget ownership in this role, I am towards the upper end of that range. I am open to discussing the overall package, including bonus and training.',
            'range,market,experience,package'],
        'fu' => [['keywords', 0, 'Et si notre budget était inférieur à votre fourchette, que proposeriez-vous ?', 'And if our budget were below your range, what would you suggest?', 'fourchette,entre,k€,euros', 'range,between,k,salary']],
    ],
    ['code' => 'gen-neg-counter', 'type' => 'negotiation', 'lvl' => [2, 5], 'diff' => 4, 'sec' => 180, 'skills' => ['negotiation', 'communication', 'decision_making'],
        'fr' => ['Nous vous proposons un salaire inférieur à vos attentes. Comment réagissez-vous ?', 'Restez positif, reformulez votre intérêt, argumentez puis proposez des alternatives concrètes.',
            ['Réaction positive et professionnelle|remercie,interesse,positif,apprecie,motivation', 'Argumentation fondée|marche,experience,valeur,responsabilites,competences', 'Alternatives proposées|revision,variable,prime,formation,teletravail,clause,six mois,objectifs', 'Décision réfléchie|reflechir,delai,decision,limite,acceptable'],
            ['Accepter immédiatement sans discuter', 'Réagir de façon émotionnelle ou ultimative'],
            'Je vous remercie pour cette proposition, le poste m\'intéresse vraiment. L\'écart avec le marché pour ce niveau de responsabilités reste important. Serait-il possible de prévoir une revue de salaire à six mois sur objectifs définis, ou une part variable ? Je souhaiterais disposer de 48 heures pour vous donner une réponse réfléchie.',
            'proposition,marche,revision,variable'],
        'en' => ['We are offering a salary below your expectations. How do you respond?', 'Stay positive, restate your interest, argue, then propose concrete alternatives.',
            ['Positive professional reaction|thank,interested,positive,appreciate,motivat', 'Grounded argument|market,experience,value,responsibilit,skills', 'Alternatives proposed|review,bonus,variable,training,remote,clause,six months,objectives', 'Considered decision|think,time,decision,limit,acceptable'],
            ['Accepting immediately without discussion', 'Reacting emotionally or with an ultimatum'],
            'Thank you for the offer, I am genuinely interested in the role. The gap with the market for this level of responsibility remains significant. Could we plan a salary review after six months against agreed objectives, or add a bonus component? I would like 48 hours to give you a considered answer.',
            'offer,market,review,bonus'],
    ],
    ['code' => 'gen-neg-internal-promotion', 'type' => 'negotiation', 'lvl' => [3, 5], 'diff' => 4, 'sec' => 180, 'skills' => ['negotiation', 'results_orientation'],
        'fr' => ['Dans le cadre de votre promotion interne, comment argumentez-vous votre nouvelle rémunération ?', 'Appuyez-vous sur vos résultats, l\'évolution des responsabilités et les références internes ou de marché.',
            ['Résultats obtenus|resultat,objectif,atteint,depasse,chiffre,%', 'Évolution des responsabilités|responsabilites,equipe,budget,perimetre,management', 'Références internes et marché|grille,marche,equite,niveau,reference', 'Proposition claire|propose,souhaite,montant,fourchette,%'],
            ['Comparer nommément sa rémunération à celle d\'un collègue', 'Ne pas chiffrer sa demande'],
            'Sur les deux dernières années, j\'ai dépassé mes objectifs de 15 % et repris l\'encadrement de trois personnes. Le nouveau poste ajoute un budget de 1,2 M€. En me référant à la grille interne du niveau supérieur et aux données du marché, je propose une augmentation de 12 %, avec un point d\'étape à un an.',
            'resultat,responsabilites,grille,propose'],
        'en' => ['In the context of your internal promotion, how do you argue for your new pay?', 'Rely on results, increased responsibilities and internal or market references.',
            ['Results achieved|result,objective,met,exceeded,figure,%', 'Increased responsibilities|responsibilit,team,budget,scope,management', 'Internal and market references|grid,band,market,equity,level,benchmark', 'Clear proposal|propose,would like,amount,range,%'],
            ['Comparing your pay to a named colleague', 'Not quantifying the request'],
            'Over the last two years I exceeded my targets by 15 % and took over managing three people. The new role adds a 1.2M budget. Referring to the internal band for the next level and market data, I propose a 12 % increase with a review after one year.',
            'results,responsibilities,band,propose'],
    ],

