            ['Results without figures', 'Describing difficulties without solutions'],
            'Our training programme had to reach 500 staff with a budget cut by 30 %. I prioritised high impact modules, trained local relay trainers and used remote sessions. We trained 560 staff and satisfaction reached 87 %.',
            'objective,resources,prioritised,result'],
    ],
    ['code' => 'gen-int-motivation-un', 'type' => 'international', 'lvl' => [1, 5], 'diff' => 2, 'sec' => 180, 'skills' => ['motivation_fit', 'multicultural'],
